p=Path(__file__).parent;r=json.loads((p/'windows.json').read_text());sw=r['server_windows'];cw=r['client_windows'];nw=r['network_windows']
def st(a):
 s=sorted(a);return {'count':len(s),'mean':statistics.mean(s),'median':statistics.median(s),'p95':s[min(len(s)-1,max(0,math.ceil(.95*len(s))-1))],'min':min(s),'p95_definition':'nearest-rank ceil(0.95*n)-1'}
def tv(n):return [w['telemetry'][n] for w in cw if n in w['telemetry']]
pred=[sum(w['telemetry'][n] for n in ('wire_ms','queue_ms','decode_ms','decode_to_selection_ms','selection_to_predicted_ms')) for w in cw if all(n in w['telemetry'] for n in ('wire_ms','queue_ms','decode_ms','decode_to_selection_ms','selection_to_predicted_ms'))]
summary={'run_guard':{'final_host_guard':'REVERTED 29f74462','shutdown_validation':'shutdown markers occur after retained measurement windows; final server exit status 0; shutdown behavior excluded from metrics'},'workload':{'scenes':['forest','crowd','dark'],'switch_every_stereo_frames':1800,'switch_period_approx_s':20,'codec':'auto500 tail64 Zstd native RGB888 credit off newest-direct ready-wait 0'},'series':{'encoder_fps':st([w['frames']/w['seconds'] for w in sw]),'new_source_fps':st([w['new_source']/w['seconds'] for w in cw]),'app_renderloop_fps':st([w['renderloop_fps'] for w in cw]),'bytes_payload_mbps':st([w['payload_mbps'] for w in sw]),'wire_ms':st(tv('wire_ms')),'own_gpu_ms':st([w['own_gpu_ms'] for w in cw if w.get('own_gpu_ms') is not None]),'predicted_runtime_first_arrival_to_prediction_ms':st(pred),'network_holes_total':sum(w['holes'] for w in nw),'network_frames_closed':sum(w['frames_closed'] for w in nw),'min_window_new_source_fps':min(w['new_source']/w['seconds'] for w in cw),'window_count':len(cw)},'late_regression':{'window_indices':[557,558,571,576],'min_fresh_window_index':557,'observed_holes':[61,76,2,1],'citations':['client log line 25127','client log line 25172','client log line 25902','client log line 26175'],'note':'late-run burst with sharp cadence/loss regression; retained as valid evidence, no cause inferred'},'runtime_reported_gpu_temp_c':{'min_positive':55.8,'max':79.9,'note':'PxrMetric runtime-reported field only; not thermal proof'},'scene_switches':r['scene_switches'],'_method':{'windowing':'bundled independent complete 2-second windows','p95':'nearest-rank ceil(0.95*n)-1','predicted_runtime':'wire + queue + decode + decode-to-selection + selection-to-predicted; approximate same-client-clock estimate, no photon claim'}}
(p/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');idx=range(len(cw));fig,ax=plt.subplots(1,2,figsize=(13,5.2),dpi=170);ax[0].plot(idx,[w['frames']/w['seconds'] for w in sw],label='encoder FPS',color='#7700ff');ax[0].plot(idx,[w['new_source']/w['seconds'] for w in cw],label='new-source FPS',color='#28a');ax[0].plot(idx,[w['renderloop_fps'] for w in cw],label='app render-loop FPS',color='#777');ax[0].set_title('Window cadence');ax[0].set_xlabel('retained 2 s window order');ax[0].set_ylabel('FPS');ax[0].legend(fontsize=8);ax[0].grid(alpha=.25);wireax=ax[1].twinx();ax[1].plot(idx,[w['payload_mbps'] for w in sw],label='payload Mbps',color='#7700ff');wireax.plot(idx,[w['telemetry'].get('wire_ms',float('nan')) for w in cw],label='wire ms',color='#28a');ax[1].set_title('Payload and wire stage');ax[1].set_xlabel('retained 2 s window order');ax[1].set_ylabel('payload (Mbps)',color='#7700ff');wireax.set_ylabel('wire (ms)',color='#28a');ax[1].grid(alpha=.25);h1,l1=ax[1].get_legend_handles_labels();h2,l2=wireax.get_legend_handles_labels();ax[1].legend(h1+h2,l1+l2,fontsize=8);fig.suptitle('Scene-change soak — window means; no photon/game/head-motion claim');fig.tight_layout(rect=(0,0,1,.94));fig.savefig(p/'overview.png')
fig,ax=plt.subplots(figsize=(10,5.2),dpi=170);names=['wire_ms','queue_ms','decode_ms','decode_to_selection_ms','selection_to_predicted_ms'];
for n in names:ax.plot(idx,[w['telemetry'].get(n,float('nan')) for w in cw],label=n.replace('_ms',''))
ax.set_title('Client pipeline stage window values');ax.set_xlabel('retained 2 s window order');ax.set_ylabel('ms');ax.legend(fontsize=8);ax.grid(alpha=.25);fig.tight_layout();fig.savefig(p/'pipeline.png')
